function updateSyncUI(){const dirty=stagedRecords.size>0,conflict=records.some(r=>r.syncConflict)||[...stagedRecords.values()].some(r=>r.syncConflict),button=$('#sync-button'),state=$('#sync-state');if(!button||!state)return;const busy=button.dataset.busy==='true',view=conflict?'conflict':dirty?'pending':'clean';button.dataset.syncState=view;state.dataset.syncState=view;button.disabled=busy||!sessionToken||(!dirty&&!conflict);button.textContent=busy?'Sincronizando…':dirty?`Sincronizar (${stagedRecords.size})`:conflict?'Revisar conflictos':'Sincronizar con Sheets';button.title=conflict?'Hay cambios que requieren resolver el conflicto con Sheets antes de reintentar.':'Envía los cambios preparados a Sheets.';state.textContent=conflict?`Conflicto para revisar · ${syncTimeLabel(lastSuccessfulSync)}`:dirty?`${stagedRecords.size} cambio(s) pendiente(s) · ${syncTimeLabel(lastSuccessfulSync)}`:syncTimeLabel(lastSuccessfulSync);}
