async function persistStage(){if(!stageOwner)throw Error('Iniciá sesión para guardar el borrador en este navegador.');try{await StageStore.replace('notas',stageOwner,[...stagedRecords.values()]);}catch(_){throw Error('No se pudo guardar el borrador en IndexedDB. No se confirmó el cambio local.');}}
