async function saveRecords(list){if(stagedRecords.size+list.filter(r=>!stagedRecords.has(r.recordId)).length>100)throw Error('Límite de 100 cambios pendientes. Sincronizá antes de preparar más.');const previous=stagedRecords;stagedRecords=new Map(previous);for(const r of list){const existing=records.find(x=>x.recordId===r.recordId);r.expectedVersion=Number(r.expectedVersion??existing?.expectedVersion??0);delete r.syncConflict;stagedRecords.set(r.recordId,r);}try{await persistStage();}catch(e){stagedRecords=previous;throw e;}for(const r of list){const i=records.findIndex(x=>x.recordId===r.recordId);if(i<0)records.push(r);else records[i]=r;}updateSyncUI();render();return list.length;}
