async function persist(r){try{const saved=await saveRecord(r);toast('Cambio preparado. Tocá “Sincronizar con Sheets” para enviarlo.');return saved;}catch(e){throw e;}}
function live(type){return records.filter(r=>r.type===type&&!r.deletedAt&&(currentRole==='admin'||recordWithinScopes(r,currentScopes)));}
function recordWithinScopes(r,scopes=currentScopes){const d=r.data||{};if(r.type==='school')return scopes.some(s=>s.schoolId===r.id);if(r.type==='subject')return scopes.some(s=>s.subjectId===r.id);if(r.type==='course')return scopes.some(s=>s.courseId===r.id);if(r.type==='division')return scopes.some(s=>s.divisionId===r.id);if(r.type==='subgroup')return scopes.some(s=>s.divisionId===d.divisionId);if(r.type==='membership')return scopes.some(s=>scopeMatches(d,s));if(r.type==='student')return records.some(m=>m.type==='membership'&&m.data.studentId===r.id&&scopes.some(s=>scopeMatches(m.data,s)));if(r.type==='grade'){const a=records.find(x=>x.type==='assessment'&&x.id===d.assessmentId);return !!a&&recordWithinScopes(a,scopes)&&records.some(m=>m.type==='membership'&&m.data.studentId===d.studentId&&scopes.some(s=>scopeMatches(m.data,s)));}if(['assessment','schedule','attendance','observation','topic'].includes(r.type))return scopes.some(s=>scopeMatches(d,s))&&(!d.studentId||records.some(m=>m.type==='membership'&&m.data.studentId===d.studentId&&scopes.some(s=>scopeMatches(m.data,s))));if(r.type==='scale'||r.type==='cutoff')return records.some(a=>a.type==='assessment'&&(r.type==='scale'?a.data.scaleId===r.id:a.data.cutoffId===r.id)&&scopes.some(s=>scopeMatches(a.data,s)));return false;}
function scopeMatches(d,s){return d.schoolId===s.schoolId&&d.subjectId===s.subjectId&&d.courseId===s.courseId&&d.divisionId===s.divisionId;}
function getOne(type,id){return live(type).find(r=>r.id===id);}

async function apiRequest(action,data={},timeout=30000){if(action!=='auth'&&!sessionToken)throw Error('LOGIN_REQUIRED');if(!window.APP_CONFIG.API_URL)throw Error('API_NOT_CONFIGURED');const c=new AbortController(),timer=setTimeout(()=>c.abort(),timeout);try{const res=await fetch(window.APP_CONFIG.API_URL,{method:'POST',redirect:'follow',cache:'no-store',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,...data,...(sessionToken?{sessionToken}:{})}),signal:c.signal}),d=await res.json();if(!d.ok){if(['UNAUTHORIZED','SESSION_EXPIRED'].includes(d.error)){document.body.classList.remove('app-authenticated');sessionToken='';sessionStorage.removeItem('gradesSession');sessionStorage.removeItem('gradesAccess');currentUsername='';currentRole='docente';currentScopes=[];currentProfile={};stagedRecords.clear();records=[];$('#login-panel').hidden=false;$('#app-content').hidden=true;}throw Error(d.error||'API_ERROR');}return d;}catch(e){if(c.signal.aborted)throw Error('REQUEST_TIMEOUT');throw e;}finally{clearTimeout(timer);}}
function equalWeights(items){return Gradebook.equalWeights(items);}
function allocate(items){try{return Gradebook.allocateWeights(items);}catch(e){throw Error(e.message==='WEIGHT_REMAINDER'?'El peso no puede superar el porcentaje disponible. Ajustá los pesos sin fijar o usá Repartir por igual.':e.message);}}
function scaleValid(s){try{return Gradebook.validateScale(s);}catch(e){throw Error(e.message==='OVERLAPPING_SCALE_INTERVAL'?'Los intervalos cualitativos se superponen.':e.message==='SCALE_INTERVAL_GAP'?'Hay números sin equivalencia en la escala.':'Revisá los límites enteros de la escala.');}}
function numericValue(g,s){try{return Gradebook.numericValue(g,s);}catch(e){throw Error(e.message==='INVALID_NUMERIC_GRADE'?'La nota debe estar dentro de la escala.':e.message==='INVALID_QUALITATIVE_GRADE'?'Elegí una categoría cualitativa válida.':e.message);}}
function average(grades,assessments){return Gradebook.weightedAverage(grades,assessments,a=>getOne('scale',a.data.scaleId)?.data||{min:1,max:10,intervals:[]});}
function selected(){return Object.fromEntries(['school','subject','course','division','cutoff','subgroup'].map(k=>[k,$(`#filter-${k}`).value]));}
function fillSelect(el,items,placeholder,selected=''){const value=selected||el.value;el.innerHTML=`<option value="">${esc(placeholder)}</option>`+items.map(x=>`<option value="${esc(x.id)}">${esc(x.data.name||x.data.fullName||x.data.label||x.id)}</option>`).join('');if(items.some(x=>x.id===value))el.value=value;}
function groupContexts(){const contexts=[],seen=new Set(),add=d=>{if(!d?.schoolId||!d?.subjectId||!d?.courseId||!d?.divisionId)return;const c={schoolId:d.schoolId,subjectId:d.subjectId,courseId:d.courseId,divisionId:d.divisionId},key=JSON.stringify([c.schoolId,c.subjectId,c.courseId,c.divisionId]);if(!seen.has(key)&&(currentRole==='admin'||currentScopes.some(x=>x.schoolId===c.schoolId&&x.subjectId===c.subjectId&&x.courseId===c.courseId&&x.divisionId===c.divisionId))){seen.add(key);contexts.push(c);}};for(const type of ['membership','assessment','schedule','attendance','observation','topic'])for(const x of live(type))add(x.data);if(currentRole!=='admin')for(const x of currentScopes)add(x);return contexts;}
function classContextNames(){return{school:id=>live('school').find(x=>x.id===id)?.data.name||'',subject:id=>live('subject').find(x=>x.id===id)?.data.name||'',course:id=>live('course').find(x=>x.id===id)?.data.name||'',division:id=>live('division').find(x=>x.id===id)?.data.name||''};}
function syncClassContextOptions(){const el=$('#filter-assignment');if(!el)return;const contexts=groupContexts(),current=selected(),selectedContext={schoolId:current.school,subjectId:current.subject,courseId:current.course,divisionId:current.division},chosen=contexts.find(c=>NotesContext.key(c)===NotesContext.key(selectedContext))||(!current.school&&!current.subject&&!current.course&&!current.division?contexts[0]:null),names=classContextNames();el.innerHTML=contexts.map(c=>`<option value="${esc(NotesContext.key(c))}">${esc(NotesContext.label(c,names))}</option>`).join('')||'<option value="">No hay clases asignadas</option>';el.disabled=!contexts.length;if(chosen)el.value=NotesContext.key(chosen);else el.selectedIndex=-1;}
function renderClassContext(){const c=selected(),context={schoolId:c.school,subjectId:c.subject,courseId:c.course,divisionId:c.division},years=NotesContext.cohorts(context,live('membership'),live('student'),id=>Summary.cohortOf(id,records));$('#class-context-summary').innerHTML=`<span class="cohort-caption">Cohortes</span>${(years.length?years:['unassigned']).map(year=>`<span class="cohort-chip">${year==='unassigned'?'Pendiente':esc(year)}</span>`).join('')}`;$('#home-class-title').textContent=classContextNames().subject(c.subject)||'Elegí una clase';$('#home-class-detail').textContent=`${classContextNames().course(c.course)} · ${classContextNames().division(c.division)}${years.length?` · Cohorte ${years.filter(x=>x!=='unassigned').join(', ')||'pendiente'}`:''}`;}

function defaultFilterContext(){const contexts=groupContexts(),assessments=live('assessment'),memberships=live('membership'),preferred=assessments.find(a=>contexts.some(c=>c.schoolId===a.data.schoolId&&c.subjectId===a.data.subjectId&&c.courseId===a.data.courseId&&c.divisionId===a.data.divisionId))?.data,group=preferred||memberships.find(x=>contexts.some(c=>c.schoolId===x.data.schoolId&&c.subjectId===x.data.subjectId&&c.courseId===x.data.courseId&&c.divisionId===x.data.divisionId))?.data||contexts[0]||{};return{school:group.schoolId||'',subject:group.subjectId||'',course:group.courseId||'',division:group.divisionId||'',cutoff:assessments.find(a=>a.data.schoolId===group.schoolId&&a.data.subjectId===group.subjectId&&a.data.courseId===group.courseId&&a.data.divisionId===group.divisionId)?.data.cutoffId||'',subgroup:''};}
function fillSelect(el,items,placeholder,preferred=''){const value=[preferred,el.value].find(id=>id&&items.some(x=>x.id===id))||'';el.innerHTML=`<option value="">${esc(placeholder)}</option>`+items.map(x=>`<option value="${esc(x.id)}">${esc(x.data.name||x.data.fullName||x.data.label||x.id)}</option>`).join('');el.value=value;}
function refreshFilters(){const current=selected(),defaults=defaultFilterContext(),contexts=groupContexts(),score=c=>['school','subject','course','division'].reduce((n,k)=>n+(current[k]&&current[k]===c[`${k}Id`]?1:0),0),group=contexts.slice().sort((a,b)=>score(b)-score(a)||Number(b.subjectId===defaults.subject)-Number(a.subjectId===defaults.subject))[0]||{},f={school:group.schoolId||defaults.school,subject:group.subjectId||defaults.subject,course:group.courseId||defaults.course,division:group.divisionId||defaults.division};for(const [k,idKey] of [['school','schoolId'],['subject','subjectId'],['course','courseId'],['division','divisionId']]){const ids=new Set(contexts.filter(c=>k==='school'||(c.schoolId===f.school&&(k==='subject'||c.subjectId===f.subject)&&(k==='course'||c.courseId===f.course))).map(c=>c[idKey]));const items=live(k).filter(x=>ids.has(x.id));const wanted=current[k]&&ids.has(current[k])?current[k]:f[k];fillSelect($(`#filter-${k}`),items,`Elegí ${LABELS[k].toLowerCase()}`,wanted);f[k]=$(`#filter-${k}`).value;}const cutoffItems=live('cutoff').filter(x=>live('assessment').some(a=>a.data.schoolId===f.school&&a.data.subjectId===f.subject&&a.data.courseId===f.course&&a.data.divisionId===f.division&&a.data.cutoffId===x.id));const contextAssessment=live('assessment').find(a=>a.data.schoolId===f.school&&a.data.subjectId===f.subject&&a.data.courseId===f.course&&a.data.divisionId===f.division),cutoffPreferred=current.cutoff&&cutoffItems.some(x=>x.id===current.cutoff)?current.cutoff:contextAssessment?.data.cutoffId||'';fillSelect($('#filter-cutoff'),cutoffItems,'Elegí corte',cutoffPreferred);const subgroupItems=live('subgroup').filter(x=>x.data.divisionId===f.division);fillSelect($('#filter-subgroup'),subgroupItems,'Toda la división',current.subgroup&&subgroupItems.some(x=>x.id===current.subgroup)?current.subgroup:'');}
function membershipsFor(f=selected()){return live('membership').filter(x=>x.data.schoolId===f.school&&x.data.subjectId===f.subject&&x.data.courseId===f.course&&x.data.divisionId===f.division&&(!f.subgroup||(x.data.subgroupIds||[]).includes(f.subgroup)));}
function roster(){const ids=new Set(membershipsFor().map(x=>x.data.studentId));return live('student').filter(x=>ids.has(x.id)).sort((a,b)=>a.data.fullName.localeCompare(b.data.fullName,'es'));}
function assessmentsFor(f=selected()){return live('assessment').filter(x=>x.data.schoolId===f.school&&x.data.subjectId===f.subject&&x.data.courseId===f.course&&x.data.divisionId===f.division&&x.data.cutoffId===f.cutoff&&(!f.subgroup||!(x.data.subgroupIds||[]).length||(x.data.subgroupIds||[]).includes(f.subgroup)));}
function gradeFor(studentId,assessmentId){return live('grade').find(x=>x.data.studentId===studentId&&x.data.assessmentId===assessmentId);}

function presentAttendances(studentId,assessment){const d=assessment.data;return live('attendance').filter(x=>{const schedule=getOne('schedule',x.data.scheduleId)?.data;return x.data.studentId===studentId&&x.data.status==='present'&&x.data.schoolId===d.schoolId&&x.data.subjectId===d.subjectId&&x.data.courseId===d.courseId&&x.data.divisionId===d.divisionId&&schedule?.schoolId===d.schoolId&&schedule?.subjectId===d.subjectId&&schedule?.courseId===d.courseId&&schedule?.divisionId===d.divisionId&&Gradebook.scheduleMatchesDate(schedule,x.data.date);}).sort((a,b)=>b.data.date.localeCompare(a.data.date));}
function findAttendance(studentId,id){return live('attendance').find(x=>x.id===id&&x.data.studentId===studentId);}
function validGradeAttendance(studentId,assessment,attendanceId){const a=assessment?.data||assessment,attendance=findAttendance(studentId,attendanceId),d=attendance?.data,schedule=d&&getOne('schedule',d.scheduleId)?.data;return !!(d&&d.status==='present'&&d.studentId===studentId&&d.schoolId===a?.schoolId&&d.subjectId===a?.subjectId&&d.courseId===a?.courseId&&d.divisionId===a?.divisionId&&Gradebook.scheduleMatchesDate(schedule,d.date));}
function eligibleGradeAttendances(studentId,assessment,subgroupIds=[]){return presentAttendances(studentId,assessment).filter(x=>validGradeAttendance(studentId,assessment,x.id)&&(!subgroupIds.length||live('membership').some(m=>m.data.studentId===studentId&&m.data.schoolId===assessment.data.schoolId&&m.data.subjectId===assessment.data.subjectId&&m.data.courseId===assessment.data.courseId&&m.data.divisionId===assessment.data.division&&subgroupIds.some(id=>(m.data.subgroupIds||[]).includes(id)))));}
function attendanceForDate(studentId,date,f=selected(),scheduleId=$('#attendance-schedule')?.value){return live('attendance').find(x=>x.data.studentId===studentId&&x.data.date===date&&x.data.scheduleId===scheduleId&&x.data.schoolId===f.school&&x.data.subjectId===f.subject&&x.data.courseId===f.course&&x.data.divisionId===f.division);}
function schedulesFor(f=selected()){return live('schedule').filter(x=>x.data.schoolId===f.school&&x.data.subjectId===f.subject&&x.data.courseId===f.course&&x.data.divisionId===f.division).sort((a,b)=>a.data.dayOfWeek-b.data.dayOfWeek||a.data.startTime.localeCompare(b.data.startTime));}
function latestAttendanceDate(f){const dates=live('attendance').filter(x=>x.data.schoolId===f.school&&x.data.subjectId===f.subject&&x.data.courseId===f.course&&x.data.divisionId===f.division&&Gradebook.scheduleMatchesDate(getOne('schedule',x.data.scheduleId)?.data,x.data.date)).map(x=>x.data.date).sort();return dates.at(-1)||'';}
function scheduleLabel(x){return `${['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'][x.data.dayOfWeek]} · ${x.data.startTime}–${x.data.endTime}`;}
function scheduleForDate(date,scheduleId){const x=getOne('schedule',scheduleId);return x&&Gradebook.weekdayForDate(date)===Number(x.data.dayOfWeek)?x:null;}
function sessionMemberships(schedule){return live('membership').filter(m=>m.data.schoolId===schedule.data.schoolId&&m.data.subjectId===schedule.data.subjectId&&m.data.courseId===schedule.data.courseId&&m.data.divisionId===schedule.data.divisionId);}
function sessionRoster(schedule){const ids=new Set(sessionMemberships(schedule).map(x=>x.data.studentId));return live('student').filter(x=>ids.has(x.id)).sort((a,b)=>a.data.fullName.localeCompare(b.data.fullName,'es'));}
function displayScale(a){return getOne('scale',a.data.scaleId)?.data||{min:1,max:10,mode:'numeric',intervals:[]};}
function tableSearchMatches(text,query){return String(text||'').toLocaleLowerCase('es').includes(String(query||'').trim().toLocaleLowerCase('es'));}
function tableRowSearchMatches(row,query,column=''){return tableSearchMatches(column===''?row.textContent:row.cells[Number(column)]?.innerText,query);}
function stableSortRows(rows,column,direction='asc'){return rows.map((row,index)=>({row,index,value:row.cells[Number(column)]?.innerText.trim()||''})).sort((a,b)=>compareTableValues(a.value,b.value,direction)||a.index-b.index).map(x=>x.row);}
function compareTableValues(a,b,direction='asc'){return String(a||'').localeCompare(String(b||''),'es',{numeric:true,sensitivity:'base'})*(direction==='desc'?-1:1);}
function renderTableTools(id){const body=document.getElementById(id),table=body?.closest('table');if(!body||!table)return;if(table.refreshTableTools){table.refreshTableTools();return;}const bar=document.createElement('div');bar.className='table-tools';bar.innerHTML='<label>Buscar en esta tabla<input type="search" data-table-search placeholder="Filtrar filas…"></label><label>Buscar en columna<select data-table-search-column><option value="">Toda la tabla</option></select></label><label>Ordenar por<select data-table-sort><option value="">Sin ordenar</option></select></label><label>Dirección<select data-table-direction><option value="asc">A–Z</option><option value="desc">Z–A</option></select></label>';table.parentElement.insertBefore(bar,table);const search=bar.querySelector('[data-table-search]'),searchColumn=bar.querySelector('[data-table-search-column]'),sort=bar.querySelector('[data-table-sort]'),direction=bar.querySelector('[data-table-direction]');let sourceRows=[],sourceSet=new Set(),headerSignature='';const update=()=>{const current=[...body.querySelectorAll(':scope > tr')],dataRows=current.filter(r=>!r.querySelector('.empty'));for(const row of current)row.hidden=!row.querySelector('.empty')&&!!search.value&&!tableRowSearchMatches(row,search.value,searchColumn.value);const desired=sort.value?stableSortRows(sourceRows,sort.value,direction.value):sourceRows;if(desired.length===dataRows.length&&desired.some((row,i)=>row!==dataRows[i]))for(const row of desired)body.append(row);};const refreshColumns=()=>{const headers=[...(table.tHead?.rows[0]?.cells||[])],signature=headers.map(x=>x.textContent.trim()).join('\u0000');if(signature!==headerSignature){const selected=sort.selectedOptions?.[0]?.textContent||'';headerSignature=signature;const previousColumn=searchColumn.selectedOptions?.[0]?.textContent||'Toda la tabla';searchColumn.innerHTML='<option value="">Toda la tabla</option>'+headers.map((x,i)=>`<option value="${i}">${esc(x.textContent.trim())}</option>`).join('');searchColumn.value=[...searchColumn.options].find(x=>x.textContent===previousColumn)?.value||'';sort.innerHTML='<option value="">Sin ordenar</option>'+headers.map((x,i)=>`<option value="${i}">${esc(x.textContent.trim())}</option>`).join('');const match=[...sort.options].find(x=>x.textContent===selected);if(match)sort.value=match.value;}update();};table.refreshTableTools=refreshColumns;sourceRows=[...body.querySelectorAll(':scope > tr')].filter(r=>!r.querySelector('.empty'));sourceSet=new Set(sourceRows);refreshColumns();search.addEventListener('input',update);searchColumn.addEventListener('change',update);sort.addEventListener('change',update);direction.addEventListener('change',update);const observer=new MutationObserver(()=>{const rows=[...body.querySelectorAll(':scope > tr')].filter(r=>!r.querySelector('.empty')),set=new Set(rows);if(rows.length===sourceRows.length&&rows.every(r=>sourceSet.has(r)))return;sourceRows=rows;sourceSet=set;refreshColumns();});observer.observe(body,{childList:true});if(table.tHead)table.tHead.addEventListener('input',refreshColumns);}
function renderGradeClassDetails(f){const subject=live('subject').find(x=>x.id===f.subject),slots=live('schedule').filter(x=>['schoolId','subjectId','courseId','divisionId'].every(k=>x.data[k]===({schoolId:f.school,subjectId:f.subject,courseId:f.course,divisionId:f.division})[k])).sort((x,y)=>Number(x.data.dayOfWeek)-Number(y.data.dayOfWeek)||x.data.startTime.localeCompare(y.data.startTime)),days=['domingo','lunes','martes','miércoles','jueves','viernes','sábado'],school=live('school').find(x=>x.id===f.school)?.data.name||'—',course=live('course').find(x=>x.id===f.course)?.data.name||'—',division=live('division').find(x=>x.id===f.division)?.data.name||'—',staff=typeof teachers==='undefined'?[]:teachers;if(!subject){$('#grade-class-details').textContent='Elegí un grupo para ver sus materias, docentes y horarios.';return;}$('#grade-class-details').innerHTML=`<strong>${esc(subject.data.name)}</strong> · ${esc(school)} · ${esc(course)} · ${esc(division)}<br>${slots.map(x=>`${esc(staff.find(t=>t.teacherId===x.data.teacherId)?.name||'Sin docente asignado')} · ${days[Number(x.data.dayOfWeek)]} ${esc(x.data.startTime)}–${esc(x.data.endTime)}`).join('<br>')||'Sin horarios cargados'}`;}
