function renderGradebook(){const f=selected(),students=roster(),assessments=gradebookAssessmentsFor(f),query=$('#filter-student').value.trim().toLocaleLowerCase('es');renderGradeClassDetails(f);if(!f.school||!f.subject||!f.course||!f.division){$('#grade-head').innerHTML='<tr><th>Libreta</th></tr>';$('#grade-rows').innerHTML='<tr><td class="empty">Elegí escuela, materia, año y división para ver la libreta.</td></tr>';return;}if(!assessments.length){$('#grade-head').innerHTML='<tr><th>Libreta</th></tr>';$('#grade-rows').innerHTML='<tr><td class="empty">No hay instancias en este año y división. Creá una para generar la planilla.</td></tr>';return;}
  $('#grade-head').innerHTML=`<tr><th>Estudiante</th><th>ID</th>${assessments.map(a=>`<th class="grade-instance">${esc(a.data.name)}<small class="grade-instance-date">${esc(a.data.date||'Sin fecha')}</small><small>${Number(a.data.weight||0)}%</small></th>`).join('')}<th>Promedio</th></tr>`;
  const filtered=students.filter(s=>`${s.data.fullName} ${s.data.studentId}`.toLocaleLowerCase('es').includes(query));$('#grade-rows').innerHTML=filtered.map(st=>{const gs=assessments.map(a=>gradeFor(st.id,a.id));const avg=average(gs.filter(Boolean),assessments);return `<tr><td><strong>${esc(st.data.fullName)}</strong></td><td>${esc(st.data.studentId)}</td>${assessments.map((a,i)=>gradeCell(st,a,gs[i])).join('')}<td><strong>${avg.value===null?'—':avg.value.toFixed(2)}</strong><small>${avg.count} notas · ${avg.weight}%</small></td></tr>`;}).join('')||'<tr><td class="empty">No hay estudiantes asignados a este grupo.</td></tr>';}
